class Solution:
    def minWindow(self, s1: str, s2: str) -> str:
        best=""; n=len(s1)
        for i in range(n):
            for j in range(i+1,n+1):
                if best and j-i>=len(best): break
                p=0
                for c in s1[i:j]:
                    if p<len(s2) and c==s2[p]: p+=1
                if p==len(s2): best=s1[i:j]; break
        return best

