class Solution:
    def minWindow(self, s1: str, s2: str) -> str:
        n,m=len(s1),len(s2); best_l=0; best_len=n+1; i=0
        while i<n:
            j=0
            while i<n:
                if s1[i]==s2[j]:
                    j+=1
                    if j==m: break
                i+=1
            if i==n: break
            end=i+1; j=m-1
            while i>=0:
                if s1[i]==s2[j]:
                    j-=1
                    if j<0: break
                i-=1
            if end-i<best_len: best_l,best_len=i,end-i
            i+=1
        return "" if best_len==n+1 else s1[best_l:best_l+best_len]

